#!/usr/bin/env python3
"""Generate src/led_table.h from the board's PINMAP.md (003's generated file).

  tools/gen_led_table.py [PINMAP.md]            write src/led_table.h
  tools/gen_led_table.py --check [PINMAP.md]    fail if src/led_table.h differs from PINMAP.md

Default PINMAP.md: ../PINMAP.md (projects/led-watch/PINMAP.md).
Each byte is (anode line << 4) | cathode line, indexed by LED number 0..71.
"""
import re, sys, pathlib

here = pathlib.Path(__file__).resolve().parent.parent
args = [a for a in sys.argv[1:] if not a.startswith("--")]
check = "--check" in sys.argv
src = pathlib.Path(args[0]) if args else here.parent / "PINMAP.md"
out = here / "src" / "led_table.h"

rows = {}
for line in src.read_text().splitlines():
    m = re.match(r"\|\s*(\d+)\s*\|\s*D\d+\s*\|\s*L(\d)\s*\|\s*L(\d)\s*\|", line)
    if m:
        rows[int(m[1])] = (int(m[2]), int(m[3]))
if sorted(rows) != list(range(72)):
    sys.exit(f"{src}: expected LED rows 0..71, found {len(rows)}")
if any(a == c for a, c in rows.values()):
    sys.exit("anode == cathode in the table")
if len(set(rows.values())) != 72:
    sys.exit("duplicate (anode, cathode) pair in the table")

body = ",\n".join(
    "    " + ", ".join(f"0x{(rows[i][0] << 4) | rows[i][1]:02X}" for i in range(r, min(r + 8, 72)))
    for r in range(0, 72, 8))
text = (f"/* GENERATED by tools/gen_led_table.py from PINMAP.md: do not edit. */\n"
        f"/* Index = LED number; byte = (anode line << 4) | cathode line. */\n"
        f"#ifndef LED_TABLE_H\n#define LED_TABLE_H\n"
        f"static const unsigned char led_table[72] = {{\n{body}\n}};\n#endif\n")
if check:
    if not out.exists() or out.read_text() != text:
        sys.exit(f"{out} is out of date: run tools/gen_led_table.py")
    print("led_table.h matches", src)
else:
    out.write_text(text)
    print("wrote", out)
